CREATE TABLE settings(id boolean PRIMARY KEY DEFAULT true CHECK(id), version integer NOT NULL DEFAULT 1, public jsonb NOT NULL DEFAULT '{}', secrets bytea);
INSERT INTO settings(id,public) VALUES(true,'{"title":"星枢用户中心","registration_mode":"invite","approval_required":false,"email_allowlist":[],"show_catalog":true,"traffic_unit":"GB","registration_limit":500,"public_origin":"","domain":"","https":false}');
CREATE TABLE customers(id text PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL DEFAULT 'customer' CHECK(role IN ('admin','customer')),status text NOT NULL CHECK(status IN ('unverified','pending','active','disabled','expired')),created_at timestamptz NOT NULL DEFAULT now(),email_verified_at timestamptz);
CREATE TABLE sessions(token_hash text PRIMARY KEY,customer_id text NOT NULL REFERENCES customers(id) ON DELETE CASCADE,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE invitations(id text PRIMARY KEY,code_hash text NOT NULL UNIQUE,prefix text NOT NULL,email text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT true,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz NOT NULL,max_uses integer NOT NULL CHECK(max_uses BETWEEN 1 AND 10000),claimed integer NOT NULL DEFAULT 0 CHECK(claimed>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitation_claims(customer_id text PRIMARY KEY REFERENCES customers(id),invitation_id text NOT NULL REFERENCES invitations(id),finalized boolean NOT NULL DEFAULT false,released boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL);
CREATE TABLE email_tokens(id text PRIMARY KEY,customer_id text NOT NULL REFERENCES customers(id),purpose text NOT NULL CHECK(purpose IN ('verify','reset')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE categories(id text PRIMARY KEY,version integer NOT NULL DEFAULT 1,name text NOT NULL,description text NOT NULL DEFAULT '',sort integer NOT NULL DEFAULT 0,enabled boolean NOT NULL DEFAULT true);
CREATE TABLE plans(id text PRIMARY KEY,version integer NOT NULL DEFAULT 1,category_id text NOT NULL REFERENCES categories(id),name text NOT NULL,description text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT false,recommended boolean NOT NULL DEFAULT false,sort integer NOT NULL DEFAULT 0,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz NOT NULL,recommend_starts_at timestamptz NOT NULL DEFAULT now(),recommend_ends_at timestamptz NOT NULL,quota_bytes bigint NOT NULL CHECK(quota_bytes>0 AND quota_bytes<=9000000000000000),group_ids jsonb NOT NULL,protocols jsonb NOT NULL DEFAULT '[]',prices jsonb NOT NULL,max_devices integer NOT NULL DEFAULT 0 CHECK(max_devices BETWEEN 0 AND 20),billing_mode text NOT NULL DEFAULT 'both' CHECK(billing_mode IN ('both','uplink','downlink','max')),multiplier_milli integer NOT NULL DEFAULT 1000 CHECK(multiplier_milli BETWEEN 1 AND 100000),stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),allow_new boolean NOT NULL DEFAULT true,allow_renew boolean NOT NULL DEFAULT true);
CREATE TABLE coupons(id text PRIMARY KEY,version integer NOT NULL DEFAULT 1,code text NOT NULL UNIQUE,name text NOT NULL,enabled boolean NOT NULL DEFAULT true,kind text NOT NULL CHECK(kind IN ('fixed','percent')),amount bigint NOT NULL CHECK(amount>0),minimum bigint NOT NULL DEFAULT 0 CHECK(minimum>=0),maximum_discount bigint NOT NULL DEFAULT 0 CHECK(maximum_discount>=0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,plan_ids jsonb NOT NULL DEFAULT '[]',price_ids jsonb NOT NULL DEFAULT '[]',customer_ids jsonb NOT NULL DEFAULT '[]',new_only boolean NOT NULL DEFAULT false,max_uses integer NOT NULL DEFAULT 0 CHECK(max_uses>=0),per_customer integer NOT NULL DEFAULT 1 CHECK(per_customer BETWEEN 1 AND 10000));
CREATE TABLE orders(id text PRIMARY KEY,customer_id text NOT NULL REFERENCES customers(id),plan_id text NOT NULL REFERENCES plans(id),price_id text NOT NULL,snapshot jsonb NOT NULL,base_amount bigint NOT NULL CHECK(base_amount>=1),discount_amount bigint NOT NULL DEFAULT 0 CHECK(discount_amount>=0),payable bigint NOT NULL CHECK(payable>=1),coupon_id text REFERENCES coupons(id),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','paid','cancelled','late_paid','refund_pending','refunded')),fulfillment text NOT NULL DEFAULT 'none' CHECK(fulfillment IN ('none','queued','working','active','failed')),expires_at timestamptz NOT NULL,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),request_key text NOT NULL,request_hash text NOT NULL,UNIQUE(customer_id,request_key));
CREATE INDEX orders_owner ON orders(customer_id,created_at DESC);
CREATE INDEX orders_coupon ON orders(coupon_id,customer_id,state);
CREATE TABLE payment_channels(id text PRIMARY KEY,config bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),channel_id text NOT NULL REFERENCES payment_channels(id),out_trade_no text NOT NULL UNIQUE,trade_no text UNIQUE,state text NOT NULL DEFAULT 'created',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id));
CREATE TABLE payment_events(id text PRIMARY KEY,payment_id text REFERENCES payments(id),event_hash text NOT NULL UNIQUE,state text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_accounts(customer_id text PRIMARY KEY REFERENCES customers(id),control_user_id text NOT NULL UNIQUE,subscription_id text NOT NULL UNIQUE,plan_id text NOT NULL REFERENCES plans(id),last_order_id text NOT NULL REFERENCES orders(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE entitlement_ledger(order_id text PRIMARY KEY REFERENCES orders(id),customer_id text NOT NULL REFERENCES customers(id),control_operation text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id text PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('fulfill','mail','access','update','gateway')),subject text NOT NULL,payload bytea,state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','working','succeeded','failed','rolled_back')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,detail text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,subject));
CREATE INDEX jobs_claim ON jobs(state,available_at);
CREATE TABLE tickets(id text PRIMARY KEY,customer_id text NOT NULL REFERENCES customers(id),subject text NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_messages(id text PRIMARY KEY,ticket_id text NOT NULL REFERENCES tickets(id),customer_id text NOT NULL REFERENCES customers(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcements(id text PRIMARY KEY,title text NOT NULL,body text NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY,actor text NOT NULL,action text NOT NULL,subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);

CREATE TABLE release_cache(id boolean PRIMARY KEY CHECK(id),payload jsonb NOT NULL,checked_at timestamptz NOT NULL);
CREATE TABLE local_worker(id boolean PRIMARY KEY CHECK(id),last_seen timestamptz NOT NULL,status jsonb NOT NULL DEFAULT '{}');
